final class TokenRefresher {
    func authorizedRequest(_ request: URLRequest) async throws -> Data {
        var req = request
        req.setValue("Bearer \(currentToken)", forHTTPHeaderField: "Authorization")
        let (data, response) = try await URLSession.shared.data(for: req)
        if (response as? HTTPURLResponse)?.statusCode == 401 {
            currentToken = try await refreshToken()
            return try await authorizedRequest(request)
        }
        return data
    }
}

final class Cache {
    private var storage: [String: Data] = [:]

    func set(_ data: Data, for key: String) {
        storage[key] = data
    }

    func get(_ key: String) -> Data? {
        storage[key]
    }
}

